// Without a container, the developer becomes the wiring code.
// Every new dependency changes call sites, creation order is
// implicit, and swapping implementations for tests means editing
// production code.
import { Database } from './database';
import { UserRepository } from './user.repository';
import { UserService } from './user.service';
import { UserController } from './user.controller';

export function buildApp() {
  const db = new Database({ url: process.env.DB_URL ?? 'postgres://localhost:5432/app' });
  const repo = new UserRepository(db);
  const svc = new UserService(repo);
  const ctrl = new UserController(svc);

  // The order above is a manual topological sort. If UserService
  // also needs a CacheService, this file changes again.
  return { ctrl, svc };
}

